import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, map, catchError } from 'rxjs';
import { of } from 'rxjs';

export interface Country {
  name: string;
  code: string;
}

export interface City {
  name: string;
  country?: string;
  adminName1?: string; // State/Province
  lat?: number;
  lng?: number;
}

@Injectable({
  providedIn: 'root'
})
export class CountriesService {
  private readonly countriesNowUrl = 'https://countriesnow.space/api/v0.1/countries';

  // Fallback countries list in case API is unavailable
  private readonly fallbackCountries: Country[] = [
    { name: 'Afghanistan', code: 'AF' },
    { name: 'Albania', code: 'AL' },
    { name: 'Algeria', code: 'DZ' },
    { name: 'Argentina', code: 'AR' },
    { name: 'Australia', code: 'AU' },
    { name: 'Austria', code: 'AT' },
    { name: 'Bangladesh', code: 'BD' },
    { name: 'Belgium', code: 'BE' },
    { name: 'Brazil', code: 'BR' },
    { name: 'Canada', code: 'CA' },
    { name: 'Chile', code: 'CL' },
    { name: 'China', code: 'CN' },
    { name: 'Colombia', code: 'CO' },
    { name: 'Denmark', code: 'DK' },
    { name: 'Egypt', code: 'EG' },
    { name: 'Finland', code: 'FI' },
    { name: 'France', code: 'FR' },
    { name: 'Germany', code: 'DE' },
    { name: 'India', code: 'IN' },
    { name: 'Indonesia', code: 'ID' },
    { name: 'Italy', code: 'IT' },
    { name: 'Japan', code: 'JP' },
    { name: 'Mexico', code: 'MX' },
    { name: 'Netherlands', code: 'NL' },
    { name: 'Norway', code: 'NO' },
    { name: 'Poland', code: 'PL' },
    { name: 'Russia', code: 'RU' },
    { name: 'Saudi Arabia', code: 'SA' },
    { name: 'South Africa', code: 'ZA' },
    { name: 'South Korea', code: 'KR' },
    { name: 'Spain', code: 'ES' },
    { name: 'Sweden', code: 'SE' },
    { name: 'Switzerland', code: 'CH' },
    { name: 'Thailand', code: 'TH' },
    { name: 'Turkey', code: 'TR' },
    { name: 'United Arab Emirates', code: 'AE' },
    { name: 'United Kingdom', code: 'GB' },
    { name: 'United States', code: 'US' }
  ];

  constructor(private http: HttpClient) {}

  /**
   * Get all countries
   */
  getCountries(): Observable<Country[]> {
    return this.http.get<any>(this.countriesNowUrl).pipe(
      map(response => {
        if (response.error === false && response.data) {
          return response.data.map((country: any) => ({
            name: country.country,
            code: country.iso2
          }));
        }
        return this.fallbackCountries;
      }),
      catchError(error => {
        console.error('Error fetching countries:', error);
        return of(this.fallbackCountries);
      })
    );
  }

  /**
   * Get cities by country name using CountriesNow API
   */
  getCitiesByCountry(countryName: string): Observable<City[]> {
    if (!countryName) {
      return of([]);
    }

    return this.http.post<any>(`${this.countriesNowUrl}/cities`, { country: countryName }).pipe(
      map(response => {
        console.log('CountriesNow cities response:', response);
        if (response.error === false && response.data && Array.isArray(response.data)) {
          return response.data.map((city: string) => ({
            name: city,
            country: countryName
          }));
        }
        return [];
      }),
      catchError(error => {
        console.error('Error fetching cities from CountriesNow:', error);
        return of([]);
      })
    );
  }

  /**
   * Search for cities by name and country using CountriesNow API
   */
  searchCities(countryName: string, searchTerm: string): Observable<City[]> {
    if (!searchTerm || searchTerm.length < 2 || !countryName) {
      return of([]);
    }

    console.log('Searching cities for country:', countryName, 'with term:', searchTerm);

    return this.getCitiesByCountry(countryName).pipe(
      map(cities => {
        const term = searchTerm.toLowerCase();
        const filteredCities = cities.filter(city => 
          city.name.toLowerCase().includes(term)
        ).slice(0, 10); // Limit to 10 results
        
        console.log('Filtered cities:', filteredCities);
        return filteredCities;
      }),
      catchError(error => {
        console.error('Error filtering cities:', error);
        return of([]);
      })
    );
  }

  /**
   * Search for cities by name only (without country filter)
   * Since CountriesNow doesn't support global city search, we'll search in major countries
   */
  searchCitiesByName(searchTerm: string): Observable<City[]> {
    if (!searchTerm || searchTerm.length < 2) {
      return of([]);
    }

    console.log('Global city search for term:', searchTerm);

    // Search in major countries for global city search
    const majorCountries = ['Jordan','Iraq','Kuwait','Qatar','Bahrain','Oman','United Arab Emirates','Egypt','Saudi Arabia', 
        'United States', 'United Kingdom', 'France', 'Germany', 'Canada', 'Australia', 'Japan', 'Brazil', 'India', 'China'];
    const searchObservables = majorCountries.map(country => 
      this.getCitiesByCountry(country).pipe(
        map(cities => cities.filter(city => 
          city.name.toLowerCase().includes(searchTerm.toLowerCase())
        )),
        catchError(() => of([]))
      )
    );

    return new Observable(observer => {
      let allCities: City[] = [];
      let completed = 0;
      const total = searchObservables.length;

      searchObservables.forEach(obs => {
        obs.subscribe({
          next: (cities) => {
            allCities = allCities.concat(cities);
          },
          complete: () => {
            completed++;
            if (completed === total) {
              // Remove duplicates and limit results
              const uniqueCities = allCities
                .filter((city, index, self) => 
                  index === self.findIndex(c => c.name === city.name)
                )
                .slice(0, 15);
              
              console.log('Global search results:', uniqueCities);
              observer.next(uniqueCities);
              observer.complete();
            }
          },
          error: (error) => {
            completed++;
            if (completed === total) {
              console.log('Global search completed with errors:', allCities);
              observer.next(allCities.slice(0, 15));
              observer.complete();
            }
          }
        });
      });
    });
  }

}
